import{_ as i,o,c as l,aw as a}from"./chunks/framework.DLufY-ao.js";const t="/workbook/assets/architecture-layers.0n1pBXtq.png",p=JSON.parse('{"title":"Слои и правила","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/approaches/architecture/layers.md","filePath":"wiki/dev-commit/theory/approaches/architecture/layers.md"}'),c={name:"wiki/dev-commit/theory/approaches/architecture/layers.md"};function s(d,e,r,n,u,h){return o(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="слои-и-правила" tabindex="-1">Слои и правила <a class="header-anchor" href="#слои-и-правила" aria-label="Permalink to &quot;Слои и правила&quot;">​</a></h1><h2 id="слои" tabindex="-1">Слои <a class="header-anchor" href="#слои" aria-label="Permalink to &quot;Слои&quot;">​</a></h2><details class="details custom-block"><summary><strong><code>App Layer</code></strong> (Application Core) - запуск приложения и глобальные политики</summary><p>Включает:</p><ul><li>composition root (сборка всех сервисов и зависимостей);</li><li>глобальные провайдеры/контексты;</li><li>инфраструктурные сервисы (ошибки, observability, feature flags, i18n, device/env, healthcheck);</li><li>cross-cutting workflows;</li><li>глобальные reactive effects (подписки, уведомления, модалки, синхронизации).</li></ul></details><details class="details custom-block"><summary><strong><code>Domain Layer</code></strong> (Business Features) - каждый домен изолирован и содержит свои модели и правила</summary><p>Включает:</p><ul><li>repository (контракт и реализация доступа к данным);</li><li>store/state model (состояние и бизнес-операции фичи);</li><li>typed errors и validation rules;</li><li>доменные утилиты;</li><li>unit-тесты рядом с кодом.</li></ul></details><details class="details custom-block"><summary><strong><code>View Layer</code></strong> (Screens / Sections / Flows) - отвечает за отображение и пользовательские сценарии</summary><p>Включает:</p><ul><li>page views и section views;</li><li>локальную композицию domain-store + workflow;</li><li>форму, диалоги, интерактивные компоненты экрана;</li><li>минимальную glue-логику между UI и доменными методами.</li></ul></details><details class="details custom-block"><summary><strong><code>Shared Layer</code></strong> - общий код, который не принадлежит одному домену</summary><p>Включает:</p><ul><li>утилиты;</li><li>форматтеры и helpers;</li><li>повторно используемые алгоритмы;</li><li>примитивы, не завязанные на конкретную бизнес-фичу.</li></ul></details><details class="details custom-block"><summary><strong><code>UI Kit Layer</code></strong> - дизайн-система и переиспользуемые визуальные примитивы</summary><p>Включает:</p><ul><li>базовые UI-компоненты;</li><li>токены и стили;</li><li>low-level интерактивные элементы.</li></ul></details><h2 id="связь-слоев" tabindex="-1">Связь слоев <a class="header-anchor" href="#связь-слоев" aria-label="Permalink to &quot;Связь слоев&quot;">​</a></h2><img src="'+t+'" style="width:350px;"><ol><li><code>View</code> использует <code>Domain</code> для бизнес-логики и UI Kit для отрисовки.</li><li><code>Domain</code> может использовать <code>Shared</code>, но не <code>View</code>/<code>UI</code>.</li><li><code>App</code> оркестрирует всё: инициализация, глобальные эффекты, политики.</li><li><code>Shared</code> и <code>UI Kit</code> — нижние слои, от них зависят остальные, но они сами не знают о верхних слоях.</li></ol><h2 id="правила" tabindex="-1">Правила <a class="header-anchor" href="#правила" aria-label="Permalink to &quot;Правила&quot;">​</a></h2><h3 id="правила-зависимостеи-между-слоями" tabindex="-1">Правила зависимостей между слоями <a class="header-anchor" href="#правила-зависимостеи-между-слоями" aria-label="Permalink to &quot;Правила зависимостей между слоями&quot;">​</a></h3><ul><li><code>app</code> может зависеть от <code>domains</code>, <code>views</code>, <code>shared</code>, <code>ui-kit</code>.</li><li><code>views</code> могут зависеть от <code>domains</code>, <code>shared</code>, <code>ui-kit</code>, <code>components</code>.</li><li><code>domains</code> могут зависеть от <code>shared</code> и контрактов инфраструктуры.</li><li><code>shared</code> не должен зависеть от <code>domains</code> и <code>views</code>.</li><li><code>ui-kit</code> не должен зависеть от бизнес-доменов.</li><li>Cross-domain взаимодействие допускается только через <code>app/workflows</code> или явные контракты.</li></ul><h3 id="практическии-checklist-при-добавлении-новои-фичи" tabindex="-1">Практический checklist при добавлении новой фичи <a class="header-anchor" href="#практическии-checklist-при-добавлении-новои-фичи" aria-label="Permalink to &quot;Практический checklist при добавлении новой фичи&quot;">​</a></h3><ol><li>Создать новый домен в <code>domains/&lt;feature&gt;</code>.</li><li>Описать repository-контракт и операции чтения/изменения.</li><li>Реализовать store с явными loading/error/derived состояниями.</li><li>Если есть междоменные шаги, добавить workflow в <code>app/workflows</code>.</li><li>Добавить view/section в <code>views/&lt;feature&gt;</code>.</li><li>Подключить фичу в route как thin entrypoint.</li><li>Добавить unit-тесты для store/workflow и e2e для happy-path.</li><li>Обновить docs по фиче и архитектурным решениям.</li></ol><h3 id="состояние-и-данные" tabindex="-1">Состояние и данные <a class="header-anchor" href="#состояние-и-данные" aria-label="Permalink to &quot;Состояние и данные&quot;">​</a></h3><ul><li>Разделяйте server state и client state.</li><li>Все запросы и мутации проходят через repository.</li><li>После mutation явно фиксируйте стратегию консистентности: <code>invalidate</code>, <code>selective refetch</code>, <code>optimistic update</code> (если применимо).</li><li>Derived-состояние должно вычисляться рядом с state-моделью, а не в UI.</li></ul>',17)])])}const k=i(c,[["render",s]]);export{p as __pageData,k as default};
